internal bool ReleaseAttempted, ReleaseSucceeded;
internal int ReleaseWin32Error;
protected override bool ReleaseHandle() { ReleaseAttempted = true; ReleaseSucceeded = Native.CloseHandle(handle); ReleaseWin32Error = ReleaseSucceeded ? 0 : Marshal.GetLastWin32Error(); return ReleaseSucceeded; }

    public struct BufferedCounterSample
    {
        public long ReadQpcBefore, ReadQpcAfter, WaitQpcBefore, WaitQpcAfter, ScheduledQpc;
        public uint WaitMilliseconds, ScheduleWaitResult, WaitBefore, WaitAfter;
        public ulong Creation100ns, Exit100ns, Kernel100ns, User100ns, Cycles;
        public int TimesWin32Error, CyclesWin32Error, ScheduleWaitWin32Error;
        public bool TimesSucceeded, CyclesSucceeded, FinalPartial;
    }
    public sealed class BufferedCounterTrace
    {
        public string Status, Error;
        public long Frequency, StartedQpc, EndedQpc, StartedUtcTicks, EndedUtcTicks;
        public int Count, IntervalMilliseconds, DurationMilliseconds;
        public BufferedCounterSample[] Samples;
    }
    internal static class BufferedCadence
    {
        internal static long NextDue(long actualReadEnd, long periodTicks)
        { return checked(actualReadEnd + periodTicks); }
        internal static uint WaitMilliseconds(long now, long due, long deadline, long frequency)
        {
            long target = Math.Min(due, deadline);
            if (now >= target) return 0;
            return checked((uint)Math.Max(1, Math.Ceiling((target - now) * 1000.0 / frequency)));
        }
    }

    public sealed class ReadOnlyCounters : IDisposable

        public bool HandleReleaseAttempted { get { return held.ReleaseAttempted; } }
        public bool HandleReleaseSucceeded { get { return held.ReleaseSucceeded; } }
        public int HandleReleaseWin32Error { get { return held.ReleaseWin32Error; } }

        private BufferedCounterSample ReadNumeric()
        {
            BufferedCounterSample result = new BufferedCounterSample();
            result.ReadQpcBefore = QpcNow();
            result.WaitBefore = Native.WaitForSingleObject(held, 0);
            Native.FileTime created, exited, kernel, user;
            result.TimesSucceeded = Native.GetProcessTimes(held, out created, out exited, out kernel, out user);
            result.TimesWin32Error = result.TimesSucceeded ? 0 : Marshal.GetLastWin32Error();
            if (result.TimesSucceeded) {
                result.Creation100ns = created.Value; result.Exit100ns = exited.Value;
                result.Kernel100ns = kernel.Value; result.User100ns = user.Value;
            }
            ulong cycles;
            result.CyclesSucceeded = Native.QueryProcessCycleTime(held, out cycles);
            result.CyclesWin32Error = result.CyclesSucceeded ? 0 : Marshal.GetLastWin32Error();
            if (result.CyclesSucceeded) result.Cycles = cycles;
            result.WaitAfter = Native.WaitForSingleObject(held, 0);
            result.ReadQpcAfter = QpcNow();
            return result;
        }

        // Development observer only. No JSON, file I/O, thread discovery or
        // callback runs between these reads; numeric samples occupy a fixed array.
        // A delayed read schedules the next read from its real end, never by
        // replaying missed nominal slots. QPC stamps remain the authority.
        public BufferedCounterTrace CaptureBuffered(int durationMilliseconds, int intervalMilliseconds, string expectedBirth)
        {
            if (durationMilliseconds < 10000 || durationMilliseconds > 600000)
                throw new ArgumentOutOfRangeException("durationMilliseconds");
            if (intervalMilliseconds < 100 || intervalMilliseconds > 1000)
                throw new ArgumentOutOfRangeException("intervalMilliseconds");
            ulong birth;
            if (!UInt64.TryParse(expectedBirth, NumberStyles.None, Invariant, out birth) || birth == 0)
                throw new ArgumentException("Exact creation FILETIME is required.", "expectedBirth");
            BufferedCounterTrace trace = new BufferedCounterTrace {
                Status = "INCOMPLETE", Frequency = QpcFrequency(),
                DurationMilliseconds = durationMilliseconds, IntervalMilliseconds = intervalMilliseconds,
                Samples = new BufferedCounterSample[durationMilliseconds / intervalMilliseconds + 2]
            };
            trace.StartedUtcTicks = DateTime.UtcNow.Ticks;
            trace.StartedQpc = QpcNow();
            long deadline = checked(trace.StartedQpc + (long)Math.Ceiling(durationMilliseconds * (trace.Frequency / 1000.0)));
            long period = checked((long)Math.Ceiling(intervalMilliseconds * (trace.Frequency / 1000.0)));
            long due = trace.StartedQpc;
            try {
                while (trace.Count < trace.Samples.Length) {
                    long beforeWait = QpcNow();
                    uint waitMs = trace.Count == 0 ? 0 : BufferedCadence.WaitMilliseconds(beforeWait, due, deadline, trace.Frequency);
                    uint waitResult = 258;
                    int waitError = 0;
                    if (waitMs != 0) {
                        waitResult = Native.WaitForSingleObject(held, waitMs);
                        if (waitResult == 0xffffffff) waitError = Marshal.GetLastWin32Error();
                    }
                    long afterWait = QpcNow();
                    if (waitResult == 258 && trace.Count != 0 && afterWait < Math.Min(due, deadline))
                        continue; // Early return is not a fabricated sample.
                    BufferedCounterSample sample = ReadNumeric();
                    sample.WaitQpcBefore = beforeWait; sample.WaitQpcAfter = afterWait;
                    sample.WaitMilliseconds = waitMs; sample.ScheduleWaitResult = waitResult;
                    sample.ScheduleWaitWin32Error = waitError; sample.ScheduledQpc = Math.Min(due, deadline);
                    sample.FinalPartial = trace.Count != 0 && due > deadline;
                    trace.Samples[trace.Count++] = sample;
                    if (waitResult != 0 && waitResult != 258) {
                        trace.Status = "WAIT_ERROR"; break;
                    }
                    if (!sample.TimesSucceeded || !sample.CyclesSucceeded || sample.ReadQpcAfter < sample.ReadQpcBefore) {
                        trace.Status = "COUNTER_ERROR"; break;
                    }
                    if (sample.Creation100ns != birth) {
                        trace.Status = "IDENTITY_ERROR"; break;
                    }
                    if (waitResult == 0 || sample.WaitBefore == 0 || sample.WaitAfter == 0) {
                        trace.Status = "EXITED"; break;
                    }
                    if (sample.WaitBefore != 258 || sample.WaitAfter != 258) {
                        trace.Status = "LIVENESS_ERROR"; break;
                    }
                    if (sample.ReadQpcAfter >= deadline) {
                        trace.Status = "COUNTERS_COLLECTED"; break;
                    }
                    due = BufferedCadence.NextDue(sample.ReadQpcAfter, period);
                }
                if (trace.Status == "INCOMPLETE") trace.Error = "Fixed sample capacity exhausted; no buffer growth.";
            }
            catch (Exception error) { trace.Status = "CALL_ERROR"; trace.Error = error.GetType().Name + ": " + error.Message; }
            finally { trace.EndedQpc = QpcNow(); trace.EndedUtcTicks = DateTime.UtcNow.Ticks; }
            return trace;
        }

        public void Dispose() { held.Dispose(); }
